#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    vector<int> prev(C);
    for (int c = 0; c < C; ++c) cin >> prev[c];

    long long ans = max(L, C);

    if (C >= 2) {
        vector<int> height(C - 1, 0);
        vector<int> diff(C), cur(C);

        for (int r = 1; r < L; ++r) {
            for (int c = 0; c < C; ++c) {
                cin >> cur[c];
                diff[c] = cur[c] - prev[c];
            }
            prev = cur;

            int m = C - 1;
            for (int e = 0; e < m; ++e) {
                if (diff[e] < diff[e + 1]) height[e] = 0;
                else ++height[e];
            }

            vector<pair<int, int>> st;
            st.reserve(m + 1);

            for (int i = 0; i <= m; ++i) {
                int h = (i == m ? 0 : height[i]);
                int start = i;

                while (!st.empty() && st.back().first > h) {
                    int ph = st.back().first;
                    int ps = st.back().second;
                    st.pop_back();

                    int width = i - ps;
                    long long area = 1LL * (ph + 1) * (width + 1);
                    if (area > ans) ans = area;

                    start = ps;
                }

                if (st.empty() || st.back().first < h) {
                    st.push_back({h, start});
                }
            }
        }
    } else {
        for (int r = 1; r < L; ++r) {
            int x;
            cin >> x;
        }
    }

    cout << ans << '\n';
    return 0;
}
